class Solution {
public:
    double calculateTax(std::vector<std::vector<int>>& brackets, int income) {
        double total_tax = 0.0;
        int prev = 0;
        for (const auto& b : brackets) {
            if (income <= prev) break;
            int taxable = std::min(income, b[0]) - prev;
            total_tax += taxable * ((double)b[1] / 100.0);
            prev = b[0];
        }
        return total_tax;
    }
};

class Solution {
    public double calculateTax(int[][] brackets, int income) {
        double totalTax = 0.0;
        int prev = 0;
        for (int[] b : brackets) {
            if (income <= prev) break;
            int taxable = Math.min(income, b[0]) - prev;
            totalTax += taxable * ((double) b[1] / 100.0);
            prev = b[0];
        }
        return totalTax;
    }
}

var calculateTax = function(brackets, income) {
    let totalTax = 0.0;
    let prev = 0;
    for (const [upper, percent] of brackets) {
        if (income <= prev) break;
        const taxable = Math.min(income, upper) - prev;
        totalTax += taxable * (percent / 100.0);
        prev = upper;
    }
    return totalTax;
};
